-- Stall photos, contact details and pricing
-- (photos: Wikimedia Commons, free licences).
-- Run in: Supabase Dashboard -> SQL Editor -> New query
-- Resets stalls and the demo application queue: deletes existing rows,
-- then inserts everything. Safe to run multiple times.

alter table public.stalls add column if not exists contact_email text;
alter table public.stalls add column if not exists contact_phone text;
alter table public.stalls add column if not exists price_info text;
alter table public.applications add column if not exists price_info text;

delete from public.applications where business_name in ('PoppyScotland Collection', 'Braehead Candle Co.', 'Loch Lomond Honey Farm', 'Churros del Sol', 'Argyll Leathercraft', 'Silver & Selkie Jewellery', 'Prosecco & Frost Bar', 'Storytelling Yurt');

-- Demo applications waiting in the admin review queue

delete from public.stalls;

